def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    mod = 1_000_000_007

    transitions = [{}]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            if ch not in transitions[state]:
                transitions[state][ch] = len(transitions)
                transitions.append({})
                terminal.append(False)
            state = transitions[state][ch]
        terminal[state] = True

    from collections import deque

    failure = [0] * len(transitions)
    queue = deque()

    for ch in alphabet:
        if ch in transitions[0]:
            queue.append(transitions[0][ch])
        else:
            transitions[0][ch] = 0

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for ch in alphabet:
            if ch in transitions[state]:
                child = transitions[state][ch]
                failure[child] = transitions[failure[state]][ch]
                queue.append(child)
            else:
                transitions[state][ch] = transitions[failure[state]][ch]

    states = [state for state in range(len(transitions)) if not terminal[state]]
    index = {state: i for i, state in enumerate(states)}
    size = len(states)

    matrix = [[0] * size for _ in range(size)]
    for state in states:
        row = matrix[index[state]]
        for ch in alphabet:
            target = transitions[state][ch]
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    def multiply_vector(vec, mat):
        result = [0] * size
        for i, value in enumerate(vec):
            if value:
                for j, entry in enumerate(mat[i]):
                    if entry:
                        result[j] += value * entry
        return [value % mod for value in result]

    def multiply_matrices(a, b):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for k, value in enumerate(a[i]):
                if value:
                    for j, entry in enumerate(b[k]):
                        if entry:
                            result[i][j] += value * entry
            result[i] = [value % mod for value in result[i]]
        return result

    while n:
        if n & 1:
            vector = multiply_vector(vector, matrix)
        n >>= 1
        if n:
            matrix = multiply_matrices(matrix, matrix)

    return sum(vector) % mod
